-- Custom theming (PRD-02): per-user theme preference.
-- Hand-written migration (not generated by drizzle-kit) — applied by wrangler d1,
-- matching the incremental convention of 0004/0006. The repo gitignores
-- drizzle/meta, so drizzle-kit cannot produce a reliable incremental diff;
-- migrations are authored as forward-only SQL and applied via
-- `wrangler d1 migrations apply <db> --remote`.

-- Nullable column: NULL = follow the system default theme; otherwise a compiled
-- theme name from the manifest. Nullable add is a safe, non-breaking change on D1.
ALTER TABLE `users` ADD `theme` text;
